param([string]$MigrationPath='sql/updates/world/2026_10_27_17_malgalor_scene_replacement.sql',[switch]$VerifyNativeCatalog,[switch]$VerifyLive)
$ErrorActionPreference='Stop';$repo=[IO.Path]::GetFullPath("$PSScriptRoot/../..");$out="$repo/build-extractors/runtime-test/malgalor-data"
& "$PSScriptRoot/Invoke-WithRuntimeDiagnostics.ps1" -EvidenceDirectory $out -RuntimeDirectories @($out,$repo,"$repo/build-extractors/runtime-test/legion-legendary-catalog") -Test {
 $db=(Get-Content "$repo/build-extractors/bin/Release/worldserver.conf"|Where-Object {$_ -match '^WorldDatabaseInfo\s*='}).Split('"')[1].Split(';')
 function Query([string]$sql,[bool]$refusal=$false){$prior=$env:MYSQL_PWD;$priorErrors=$ErrorActionPreference;try{$env:MYSQL_PWD=$db[3];$ErrorActionPreference='Continue';$rows=@($sql|& C:/wamp64/bin/mariadb/mariadb11.4.9/bin/mysql.exe --host=$($db[0]) --port=$($db[1]) --user=$($db[2]) --database=$($db[4]) --batch --raw --skip-column-names 2> "$out/stderr.txt");$code=$LASTEXITCODE}finally{$env:MYSQL_PWD=$prior;$ErrorActionPreference=$priorErrors};if($refusal){if(!$code -or (Get-Content "$out/stderr.txt" -Raw) -notmatch 'Malgalor scene197593 custom binding differs'){throw 'Expected scene custom binding refusal absent'};Copy-Item "$out/stderr.txt" "$out/expected-custom-refusal.txt";'PASS expected custom scene refusal (counterfactual)'}else{if($code -or (Get-Item "$out/stderr.txt").Length){Get-Content "$out/stderr.txt";throw 'Malgalor data query failed'};if($rows -match '^FAIL'){throw 'Malgalor data differs'};$rows}}
 $migration=Get-Content "$repo/$MigrationPath" -Raw
 $setup="CREATE TEMPORARY TABLE shape LIKE spell_script_names;CREATE TEMPORARY TABLE spell_script_names LIKE shape;INSERT INTO spell_script_names VALUES(123,'preserve_other');"
 $check="SELECT IF((SELECT COUNT(*) FROM spell_script_names WHERE spell_id=197593 AND ScriptName='spell_warrior_malgalor_arrival')=1 AND (SELECT COUNT(*) FROM spell_script_names WHERE spell_id=123 AND ScriptName='preserve_other')=1 AND (SELECT COUNT(*) FROM spell_script_names)=2,'PASS scene binding/unrelated preservation','FAIL scene binding');"
 Query ($setup+$migration+$check+$migration+$check)
 Query ($setup+"INSERT INTO spell_script_names VALUES(197593,'preserve_custom');"+$migration) $true
 Query "SET SESSION TRANSACTION READ ONLY;SELECT IF((SELECT COUNT(*) FROM creature WHERE id=92608 AND map=1500)=1 AND (SELECT COUNT(*) FROM creature WHERE guid=361167 AND id=92608 AND map=1500)=1,'PASS single real Malgalor source','FAIL Malgalor source');SELECT IF((SELECT COUNT(*) FROM spell_scene WHERE MiscValue=1144 AND SceneScriptPackageID=1515 AND PlaybackFlags=25 AND CustomDuration=0)=1,'PASS original native scene binding/flags','FAIL scene1144');"
 if($VerifyLive){$hash=(Get-FileHash "$repo/$MigrationPath" -Algorithm SHA1).Hash;Query "SET SESSION TRANSACTION READ ONLY;SELECT IF((SELECT COUNT(*) FROM spell_script_names WHERE spell_id=197593 AND ScriptName='spell_warrior_malgalor_arrival')=1,'PASS live script binding','FAIL live binding');SELECT IF((SELECT COUNT(*) FROM updates WHERE name='2026_10_27_17_malgalor_scene_replacement.sql' AND state='RELEASED' AND hash='$hash')=1,'PASS live updater/hash','FAIL live updater/hash');"}
 if($VerifyNativeCatalog){$priorConfig=$env:LEGION_DIALOGUE_CONFIG;try{$env:LEGION_DIALOGUE_CONFIG="$repo/build-extractors/bin/Release/worldserver.conf";& "$repo/tools/research/Read-LegionLegendaryCatalog.ps1" -SourceFile MalgalorCatalog.cpp -ProbeName MalgalorCatalog -OutputFile "$out/catalog.tsv"}finally{$env:LEGION_DIALOGUE_CONFIG=$priorConfig}
  & "$repo/tools/research/Read-LegionLegendaryCatalog.ps1" -SourceFile MalgalorSceneCatalog.cpp -ProbeName MalgalorSceneCatalog -OutputFile "$out/scene1515.txt"
  $catalog=Get-Content "$out/catalog.tsv" -Raw;$scene=Get-Content "$out/scene1515.txt" -Raw
  foreach($expected in @('CRITERIA\t45777\t92\t46881','STEP_REWARD\t4\t0','EFFECT\t197593\t0\t6\t430\t1144','DURATION\t197593\t30000','EFFECT\t185673\t0\t6\t428','EFFECT\t185674\t1\t28\t0\t93818\t719')){if($catalog -notmatch $expected){throw "Native Malgalor metadata differs: $expected"}}
  foreach($expected in @('SmoothPhaseSpawnActor\( malgalorCreatureID, -2213.38','local malgalorCreatureID = 92608','createData.smoothPhase = true','WaitForSmoothPhase\( createData \)','malgalor:BroadcastTextStereo','scene:EndScene\(\)')){if($scene -notmatch $expected){throw "Native scene1515 differs: $expected"}}
  'PASS native26972 effects/hotfixes, real933 victory/no auto reward, native fake-death/summon719,30s aura and complete base-only scene1515 package including SmoothPhase source replacement.'
 }
}
